/* @lc app=leetcode id=3546 lang=kotlin */ class Solution { fun canPartitionGrid(grid: Array<IntArray>): Boolean = grid.sumOf { r -> r.sumOf { it.toLong() } }.let { tot -> grid.map { r -> r.sumOf { it.toLong() } }.runningFold(0L) { a, b -> a + b }.let { rp -> (1 until grid.size).any { rp[it] * 2 == tot } } || (0 until grid[0].size).map { j -> grid.sumOf { it[j].toLong() } }.runningFold(0L) { a, b -> a + b }.let { cp -> (1 until grid[0].size).any { cp[it] * 2 == tot } } } }